// Weekly radar: winning ads, new launches (search run) + new and stopped ads (monitor run), one message.
function cfg() { try { return $('Configure radar').first().json || {}; } catch (e) { return {}; } }
const config = cfg();
const daysThreshold = Number(config.daysThreshold) || 30;
function rowsOf(nodeName) {
  let items = [];
  try { items = $(nodeName).all(); } catch (e) { return { rows: [], error: `${nodeName} did not run` }; }
  const rows = [];
  let error = null;
  for (const it of items) {
    const j = it.json == null ? {} : it.json;
    if (Array.isArray(j)) rows.push(...j);
    else if (j.error || j.errorMessage) error = String(j.error && typeof j.error === 'object' ? (j.error.message || JSON.stringify(j.error)) : (j.error || j.errorMessage));
    else if (Object.keys(j).length) rows.push(j);
  }
  return { rows, error };
}
const cur = rowsOf('Get current ads');
const mon = rowsOf('Check new and stopped ads');
const ads = cur.rows.filter((r) => r.status === 'ok');
const summaries = cur.rows.filter((r) => r.status === 'domain_summary');
const noAds = cur.rows.filter((r) => r.status && !['ok', 'domain_summary'].includes(r.status));
const winners = ads.filter((r) => r.isWinningAd).sort((a, b) => (b.daysActive || 0) - (a.daysActive || 0));
const launches = ads.filter((r) => r.isNewLaunch);
const newAds = mon.rows.filter((r) => r.alert === 'NEW_AD');
const stopped = mon.rows.filter((r) => r.alert === 'STOPPED_AD');
const promos = [...new Set(ads.flatMap((r) => [...(r.detectedPromoCodes || []), ...(r.detectedDiscounts || [])]))];
const line = (r) => `• *${r.inputDomain || r.domain || '?'}* · ${r.format || 'ad'}${r.headline ? ` · "${r.headline}"` : ''}${r.daysActive != null ? ` · ${r.daysActive} days` : ''}${r.transparencyUrl ? ` · <${r.transparencyUrl}|view>` : ''}`;
const sumLine = (s) => `• *${s.inputDomain}*: ${s.activeAdsCount}/${s.adsReturned} running, ${s.winningAdsCount} winning, ${s.newLaunchesCount} new · formats T${s.formatSplit?.TEXT ?? 0}/I${s.formatSplit?.IMAGE ?? 0}/V${s.formatSplit?.VIDEO ?? 0} · oldest ${s.oldestAdDays ?? '?'} days · Google reports ${s.totalAdsReportedMin ?? '?'}–${s.totalAdsReportedMax ?? '?'} ads`;
const firstMonitor = mon.rows.length === 0 && !mon.error;
const text = [
  `*Competitor Google Ads Radar* · ${ads.length} ads checked on ${summaries.length} websites`,
  ...summaries.map(sumLine),
  `*Winning ads* (running ${daysThreshold}+ days): ${winners.length}`, ...winners.slice(0, 10).map(line),
  `*New launches* (first shown in the last 7 days): ${launches.length}`, ...launches.slice(0, 10).map(line),
  `*New ads since last check*: ${newAds.length}`, ...newAds.slice(0, 10).map(line),
  `*Stopped ads since last check*: ${stopped.length}`, ...stopped.slice(0, 10).map(line),
  firstMonitor ? '_No new or stopped ads since the last check. (The very first run only stores a baseline.)_' : '',
  promos.length ? `*Promo codes and discounts seen*: ${promos.slice(0, 15).join(', ')}` : '',
  noAds.length ? `_No ads / not checked: ${noAds.map((r) => `${r.inputDomain} (${r.status})`).join(', ')}_` : '',
  cur.error ? `_Current ads request failed: ${cur.error}_` : '',
  mon.error ? `_Monitor request failed: ${mon.error}_` : '',
].filter(Boolean).join('\n');
const notionText = text.length > 1900 ? text.slice(0, 1900) + '… (truncated: Notion allows 2,000 characters per paragraph)' : text;
return [{ json: { text, notionText, slackChannel: String(config.slackChannel || '#competitor-ads'), notionParentPageId: String(config.notionParentPageId || ''),
  title: `Google Ads Radar ${new Date().toISOString().slice(0, 10)}`, adsChecked: ads.length, winners: winners.length, launches: launches.length, newAds: newAds.length, stopped: stopped.length, promos } }];
